int ieee80211_radiotat_iter_init(struct ieee80211_radiotap_iterator *iterator,
                                 struct ieee80211_radiotap_header *radiotap_header,
                                 int max_length,
                                 const struct ieee80211_radiotap_vendor_namespaces *vns) {
    uint32_t present;
    uint32_t align;
    int ret = 0;

    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->parse_error = 0;
    iterator->current_bit = 0;
    iterator->i_index = 0;
    iterator->next_i = 0;

    if (max_length < sizeof(*radiotap_header)) {
        return -EINVAL;
    }

    if (radiotap_header->it_version != 0) {
        return -EINVAL;
    }

    if (radiotap_header->it_pad != 0) {
        return -EINVAL;
    }

    present = le16toh(radiotap_header->it_present);

    if (present == 0) {
        if (max_length > sizeof(*radiotap_header)) {
            return -EINVAL;
        }
    }

    iterator->hdr = radiotap_header;
    iterator->max_length = max_length;

    if ((present & IEEE80211_RADIOTAP_EXT) == 0) {
        iterator->present = present;
    } else {
        iterator->present = present & ~IEEE80211_RADIOTAP_EXT;
        iterator->ext = present & IEEE80211_RADIOTAP_EXT;
    }

    align = 1;
    iterator->this_arg = (uint8_t *)radiotap_header + sizeof(*radiotap_header);

    return ret;
}

int ieee80211_radiotat_iter_init(struct ieee80211_radiotap_iterator *iterator,
                                 struct ieee80211_radiotap_header *radiotap_header,
                                 int max_length,
                                 const struct ieee80211_radiotap_vendor_namespaces *vns) {
    int ret = -EINVAL;

    if (!iterator || !radiotap_header)
        return -EINVAL;

    if (max_length < sizeof(*radiotap_header))
        return -EINVAL;

    iterator->hdr = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->is_radiotap = 1;
    iterator->parse = le16toh(radiotap_header->it_present);
    iterator->arg = 0;
    iterator->current_index = 0;
    iterator->next_index = 0;
    iterator->error = 0;

    if ((iterator->parse & IEEE80211_RADIOTAP_PRESENT) &&
        (iterator->parse & IEEE80211_RADIOTAP_EXT)) {
        iterator->parse &= ~(IEEE80211_RADIOTAP_PRESENT | IEEE80211_RADIOTAP_EXT);
        iterator->parse |= le32toh(radiotap_header[1].it_next);
        iterator->parse &= ~IEEE80211_RADIOTAP_EXT;
        iterator->parse |= (iterator->parse & IEEE80211_RADIOTAP_EXT) << 16;
    }

    if (iterator->parse == 0)
        iterator->parse = IEEE80211_RADIOTAP_ALL;

    if ((iterator->parse & IEEE80211_RADIOTAP_TSFT) &&
        (iterator->max_length < (offsetof(struct ieee80211_radiotap_header, tsft) + sizeof(uint64_t))))
        return -EINVAL;

    ret = 0;
    return ret;
}

int ieee80211_radiotat_iter_init(struct ieee80211_radiotap_iterator *iterator,
                                 struct ieee80211_radiotap_header *radiotap_header,
                                 int max_length,
                                 const struct ieee80211_radiotap_vendor_namespaces *vns) {
    uint8_t *cursor;
    const uint8_t *end;
    uint8_t *ext;

    if (radiotap_header->it_version != 0)
        return -EINVAL;

    iterator->hdr = radiotap_header;
    iterator->vns = vns;
    iterator->is_radiotap = 1;
    iterator->parse_result = 0;
    iterator->current_index = 0;

    cursor = (uint8_t *)&radiotap_header[1];
    end = (const uint8_t *)radiotap_header + max_length;

    if (radiotap_header->it_len < sizeof(struct ieee80211_radiotap_header))
        return -EINVAL;

    if ((radiotap_header->it_len & IEEE80211_RADIOTAP_HEADER_EXT_MASK) != 0)
        return -EINVAL;

    if (radiotap_header->it_len > max_length)
        return -EINVAL;

    if (radiotap_header->it_present == 0)
        return -EINVAL;

    while (cursor < end) {
        uint32_t field;
        uint8_t field_type;
        uint8_t field_arg;
        uint8_t field_length;
        uint32_t present = le32toh(radiotap_header->it_present);
        int ext_iter = 0;

        while (present != 0) {
            int i;
            field = hweight32(present) - 1;

            for (i = 0; i < IEEE80211_RADIOTAP_NUM_ITEMS; i++) {
                if (rtap_item_list[i].field == field) {
                    field_type = rtap_item_list[i].field;
                    field_arg = rtap_item_list[i].arg;
                    field_length = rtap_item_list[i].length;

                    if ((cursor + field_length) > end)
                        return -EINVAL;

                    iterator->this_arg = cursor;
                    iterator->this_arg_len = field_length;
                    iterator->this_iter = ext_iter;
                    iterator->this_type = field_type;
                    iterator->this_arg = cursor;

                    cursor += field_length;
                    present &= ~(1 << field);
                    iterator->current_index++;
                    break;
                }
            }

            if (i == IEEE80211_RADIOTAP_NUM_ITEMS)
                present &= ~(1 << field);
        }

        if (cursor >= end)
            break;

        if (radiotap_header->it_version & IEEE80211_RADIOTAP_HEADER_EXT)
            return -EINVAL;

        if ((radiotap_header->it_present & IEEE80211_RADIOTAP_EXT) == 0)
            break;

        ext = cursor;

        if ((cursor + sizeof(uint32_t)) > end)
            return -EINVAL;

        present = le32toh(*((uint32_t *)cursor));
        cursor += sizeof(uint32_t);
        ext_iter = 1;
    }

    if (cursor > end)
        return -EINVAL;

    iterator->parse_result = 0;
    return 0;
}

int ieee80211_radiotat_iter_init(struct ieee80211_radiotap_iterator *iterator,
                                 struct ieee80211_radiotap_header *radiotap_header,
                                 int max_length,
                                 const struct ieee80211_radiotap_vendor_namespaces *vns) {
    uint32_t bitmap;
    int i;

    /* Validate header and max_length */
    if (!iterator || !radiotap_header || max_length < 0) {
        return -EINVAL;
    }

    /* Check that the header length is valid */
    if (radiotap_header->it_len < sizeof(struct ieee80211_radiotap_header)) {
        return -EINVAL;
    }

    /* Check that max_length is at least the length of the header */
    if (max_length < radiotap_header->it_len) {
        return -EINVAL;
    }

    /* Initialize the iterator */
    iterator->hdr = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->parse = 0;
    iterator->is_present = 0;
    iterator->current_iter = 0;
    iterator->error = 0;
    iterator->version = le16toh(radiotap_header->it_version);
    iterator->aligncheck = 0;

    if (iterator->version == 0) {
        /* Version 0: Check the bitmap */
        bitmap = le32toh(radiotap_header->it_present);
        if (bitmap & IEEE80211_RADIOTAP_EXT) {
            if (radiotap_header->it_len < sizeof(struct ieee80211_radiotap_header) + sizeof(uint32_t)) {
                return -EINVAL;
            }

            /* Read the extended bitmap */
            bitmap = le32toh(((uint32_t *) (radiotap_header + 1))[0]);
            iterator->parse = bitmap;
            iterator->is_present = bitmap;
        } else {
            iterator->parse = bitmap;
            iterator->is_present = bitmap;
        }

        /* Move to the first element */
        for (i = 0; i < 32; i++) {
            if (iterator->parse & (1 << i)) {
                iterator->this_arg_index = i;
                break;
            }
        }

        if (i >= 32) {
            iterator->parse = 0;
            iterator->is_present = 0;
        }

        iterator->arg = (uint8_t *) (iterator->hdr + 1);
        if (iterator->version == 0 && (iterator->hdr->it_present & IEEE80211_RADIOTAP_EXT)) {
            iterator->arg += sizeof(uint32_t);
        }
    } else {
        return -EINVAL;
    }

    return 0;
}

int ieee80211_radiotat_iter_init(struct ieee80211_radiotap_iterator *iterator,
                                 struct ieee80211_radiotap_header *radiotap_header,
                                 int max_length,
                                 const struct ieee80211_radiotap_vendor_namespaces *vns) {
    int ret;

    if (!iterator || !radiotap_header) {
        return -EINVAL;
    }

    iterator->hdr = radiotap_header;
    iterator->max_length = max_length;
    iterator->vns = vns;
    iterator->is_radiotap = 1;
    iterator->current_table = NULL;
    iterator->parse_arg = NULL;
    iterator->parse = NULL;
    iterator->is_last = 0;
    iterator->is_first = 1;

    ret = ieee80211_radiotap_iter_set_position(iterator, 0);
    if (ret < 0) {
        return ret;
    }

    return 0;
}
